def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        freqs = {}
        hits = misses = 0

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = (args, frozenset(kwargs.items())) if typed else args
            if key in cache:
                hits += 1
                return cache[key]
            misses += 1
            result = func(*args, **kwargs)
            cache[key] = result
            freqs[key] = freqs.get(key, 0) + 1
            if len(cache) > maxsize:
                for key, freq in sorted(freqs.items(), key=lambda x: x[1]):
                    if freq == min(freqs.values()):
                        del cache[key]
                        del freqs[key]
                        break
            return result

        wrapper.cache_info = lambda: (len(cache), hits, misses)
        wrapper.cache_clear = lambda: cache.clear()
        return wrapper

    return decorator

