def extostr(e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    if not isinstance(e, Exception):
        raise TypeError("e must be an exception instance")
    if not isinstance(max_level, int):
        raise TypeError("max_level must be an integer")
    if not isinstance(max_path_level, int):
        raise TypeError("max_path_level must be an integer")
    if max_level < 0:
        raise ValueError("max_level must be a positive integer")
    if max_path_level < 0:
        raise ValueError("max_path_level must be a positive integer")

    # Get the exception type and message
    exc_type = type(e).__name__
    exc_msg = str(e)

    # Get the call stack
    call_stack = []
    for level in range(max_level):
        try:
            frame = e.__traceback__.tb_frame.f_back
            if frame is None:
                break
            call_stack.append(frame.f_code.co_name)
        except AttributeError:
            break

    # Get the path
    path = []
    for level in range(max_path_level):
        try:
            frame = e.__traceback__.tb_frame.f_back
            if frame is None:
                break
            path.append(frame.f_code.co_filename)
        except AttributeError:
            break

    # Format the exception string
    exc_str = f"{exc_type}: {exc_msg}"
    if call_stack:
        exc_str += f"\nCall stack: {', '.join(call_stack)}"
    if path:
        exc_str += f"\nPath: {', '.join(path)}"

    return exc_str

