    subprocess.run(["tar", "-xzf", archive_path, "-C", tmp_dir])

    # Find the extracted repository directory
    repo_dir = None
    for root, dirs, files in os.walk(tmp_dir):
        if "repo" in dirs:
            repo_dir = os.path.join(root, "repo")
            break
    if repo_dir is None:
        raise ValueError("Repository directory not found in archive")

    # Return the repository directory as a file URL
    return "file://" + repo_dir

